import{_ as r,r as d,o as i,c,e as n,a as e,s as l,d as t}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"Task Scheduling - October CMS - 1.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Defining schedules","slug":"defining-schedules","link":"#defining-schedules","children":[{"level":3,"title":"Schedule frequency options","slug":"schedule-frequency-options","link":"#schedule-frequency-options","children":[{"level":4,"title":"Truth test constraints","slug":"truth-test-constraints","link":"#truth-test-constraints","children":[]}]},{"level":3,"title":"Preventing task overlaps","slug":"preventing-task-overlaps","link":"#preventing-task-overlaps","children":[]}]},{"level":2,"title":"Task output","slug":"task-output","link":"#task-output","children":[]},{"level":2,"title":"Task hooks","slug":"task-hooks","link":"#task-hooks","children":[{"level":4,"title":"Pinging URLs","slug":"pinging-urls","link":"#pinging-urls","children":[]}]}],"relativePath":"1.x/plugin/scheduling.md","filePath":"1.x/plugin/scheduling.md"}'),h={name:"1.x/plugin/scheduling.md"};function u(p,o,g,m,y,f){const s=d("pre-heading"),a=d("post-heading");return i(),c("div",null,[n(s),o[0]||(o[0]=e("h1",null,"Task Scheduling",-1)),n(a),o[1]||(o[1]=l(`<p>In the past, developers have generated a Cron entry for each task they need to schedule. However, this can sometimes be a headache. Your task schedule is no longer in source control, and you must SSH into your server to add the Cron entries. The command scheduler allows you to fluently and expressively define your command schedule within the application itself, and only a single Cron entry is needed on your server.</p><blockquote><p><strong>Note</strong>: See the <a href="./../setup/installation.html#setting-up-the-scheduler">installation guide</a> for instructions on how to set up the scheduler task.</p></blockquote><h2 id="defining-schedules"><a href="#defining-schedules" class="header-anchor">#</a> Defining schedules</h2><p>You may define all of your scheduled tasks by overriding the <code>registerSchedule</code> method inside the <a href="./registration.html#registration-file">Plugin registration class</a>. The method will take a single <code>$schedule</code> argument and is used for defining commands along with their frequency.</p><p>To get started, let&#39;s look at an example of scheduling a task. In this example, we will schedule a <code>Closure</code> to be called every day at midnight. Within the <code>Closure</code> we will execute a database query to clear a table:</p><pre><code>class Plugin extends PluginBase
{
    [...]

    public function registerSchedule($schedule)
    {
        $schedule-&gt;call(function () {
            \\Db::table(&#39;recent_users&#39;)-&gt;delete();
        })-&gt;daily();
    }
}
</code></pre><p>In addition to scheduling <code>Closure</code> calls, you may also schedule <a href="./../console/commands.html">console commands</a> and operating system commands. For example, you may use the <code>command</code> method to schedule a console command:</p><pre><code>$schedule-&gt;command(&#39;cache:clear&#39;)-&gt;daily();
</code></pre><p>The <code>exec</code> command may be used to issue a command to the operating system:</p><pre><code>$schedule-&gt;exec(&#39;node /home/acme/script.js&#39;)-&gt;daily();
</code></pre><h3 id="schedule-frequency-options"><a href="#schedule-frequency-options" class="header-anchor">#</a> Schedule frequency options</h3><p>Of course, there are a variety of schedules you may assign to your task:</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>-&gt;cron(&#39;* * * * *&#39;);</code></td><td>Run the task on a custom Cron schedule</td></tr><tr><td><code>-&gt;everyMinute();</code></td><td>Run the task every minute</td></tr><tr><td><code>-&gt;everyFiveMinutes();</code></td><td>Run the task every five minutes</td></tr><tr><td><code>-&gt;everyTenMinutes();</code></td><td>Run the task every ten minutes</td></tr><tr><td><code>-&gt;everyThirtyMinutes();</code></td><td>Run the task every thirty minutes</td></tr><tr><td><code>-&gt;hourly();</code></td><td>Run the task every hour</td></tr><tr><td><code>-&gt;daily();</code></td><td>Run the task every day at midnight</td></tr><tr><td><code>-&gt;dailyAt(&#39;13:00&#39;);</code></td><td>Run the task every day at 13:00</td></tr><tr><td><code>-&gt;twiceDaily(1, 13);</code></td><td>Run the task daily at 1:00 &amp; 13:00</td></tr><tr><td><code>-&gt;weekly();</code></td><td>Run the task every week</td></tr><tr><td><code>-&gt;monthly();</code></td><td>Run the task every month</td></tr></tbody></table></div><p>These methods may be combined with additional constraints to create even more finely tuned schedules that only run on certain days of the week. For example, to schedule a command to run weekly on Monday:</p><pre><code>$schedule-&gt;call(function () {
    // Runs once a week on Monday at 13:00...
})-&gt;weekly()-&gt;mondays()-&gt;at(&#39;13:00&#39;);
</code></pre><p>Below is a list of the additional schedule constraints:</p><div class="table"><table tabindex="0"><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody><tr><td><code>-&gt;weekdays();</code></td><td>Limit the task to weekdays</td></tr><tr><td><code>-&gt;sundays();</code></td><td>Limit the task to Sunday</td></tr><tr><td><code>-&gt;mondays();</code></td><td>Limit the task to Monday</td></tr><tr><td><code>-&gt;tuesdays();</code></td><td>Limit the task to Tuesday</td></tr><tr><td><code>-&gt;wednesdays();</code></td><td>Limit the task to Wednesday</td></tr><tr><td><code>-&gt;thursdays();</code></td><td>Limit the task to Thursday</td></tr><tr><td><code>-&gt;fridays();</code></td><td>Limit the task to Friday</td></tr><tr><td><code>-&gt;saturdays();</code></td><td>Limit the task to Saturday</td></tr><tr><td><code>-&gt;when(Closure);</code></td><td>Limit the task based on a truth test</td></tr></tbody></table></div><h4 id="truth-test-constraints"><a href="#truth-test-constraints" class="header-anchor">#</a> Truth test constraints</h4><p>The <code>when</code> method may be used to limit the execution of a task based on the result of a given truth test. In other words, if the given <code>Closure</code> return <code>true</code>, the task will execute as long as no other constraining conditions prevent the task from running:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)-&gt;daily()-&gt;when(function () {
    return true;
});
</code></pre><h3 id="preventing-task-overlaps"><a href="#preventing-task-overlaps" class="header-anchor">#</a> Preventing task overlaps</h3><p>By default, scheduled tasks will be run even if the previous instance of the task is still running. To prevent this, you may use the <code>withoutOverlapping</code> method:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)-&gt;withoutOverlapping();
</code></pre><p>In this example, the <code>emails:send</code> <a href="./../console/commands.html">console command</a> will be run every minute if it is not already running. The <code>withoutOverlapping</code> method is especially useful if you have tasks that vary drastically in their execution time, preventing you from needing to predict exactly how long a given task will take.</p><h2 id="task-output"><a href="#task-output" class="header-anchor">#</a> Task output</h2><p>The scheduler provides several convenient methods for working with the output generated by scheduled tasks. First, using the <code>sendOutputTo</code> method, you may send the output to a file for later inspection:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)
         -&gt;daily()
         -&gt;sendOutputTo($filePath);
</code></pre><p>Using the <code>emailOutputTo</code> method, you may e-mail the output to an e-mail address of your choice. Note that the output must first be sent to a file using the <code>sendOutputTo</code> method. Also before e-mailing the output of a task, you should configure <a href="./../services/mail.html">mail services</a>:</p><pre><code>$schedule-&gt;command(&#39;foo&#39;)
         -&gt;daily()
         -&gt;sendOutputTo($filePath)
         -&gt;emailOutputTo(&#39;foo@example.com&#39;);
</code></pre><blockquote><p><strong>Note:</strong> The <code>emailOutputTo</code> and <code>sendOutputTo</code> methods are exclusive to the <code>command</code> method and are not supported for <code>call</code>.</p></blockquote><h2 id="task-hooks"><a href="#task-hooks" class="header-anchor">#</a> Task hooks</h2><p>Using the <code>before</code> and <code>after</code> methods, you may specify code to be executed before and after the scheduled task is complete:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)
         -&gt;daily()
         -&gt;before(function () {
             // Task is about to start...
         })
         -&gt;after(function () {
             // Task is complete...
         });
</code></pre><h4 id="pinging-urls"><a href="#pinging-urls" class="header-anchor">#</a> Pinging URLs</h4><p>Using the <code>pingBefore</code> and <code>thenPing</code> methods, the scheduler can automatically ping a given URL before or after a task is complete. This method is useful for notifying an external service that your scheduled task is commencing or complete:</p><pre><code>$schedule-&gt;command(&#39;emails:send&#39;)
         -&gt;daily()
         -&gt;pingBefore($url)
         -&gt;thenPing($url);
</code></pre>`,36)),o[2]||(o[2]=e("blockquote",null,[e("p",null,[t("You need to install "),e("a",{href:"http://octobercms.com/plugin/october-drivers",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[t("Drivers plugin"),e("span",null,[e("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[e("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),t(),e("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),t(),e("span",{class:"sr-only"},"(opens new window)")])]),t(" before you can use either the "),e("code",null,"pingBefore($url)"),t(" or "),e("code",null,"thenPing($url)"),t(" features.")])],-1))])}const b=r(h,[["render",u]]);export{v as __pageData,b as default};
